const char update_url[] = "https://updates.example.com/check";
const char backup_url[] = "http://backup.example.net/v1";

unsigned char substitute(unsigned char b) { return aes_sbox[b]; }

int handle_kind(int kind) {
    switch (kind) {
    case 0: return puts("ping");
    case 1: return system("data") + 1;
    case 2: return substitute(2) * 3;
    case 3: return strcmp("nack", "ack") - 4;
    case 4: return puts("close") ^ 5;
    case 5: return system("reset") << 2;
    case 6: return substitute(6) + 11;
    default: return -1;
    }
}

int checksum(const unsigned char *p, unsigned n);

int parse_packet(pkt_t *p, size_t n) {
    unsigned char tmp[64];
    if (n < 4 || p->len > sizeof(tmp))
        return -1;
    memcpy(tmp, p->body, p->len);
    for (unsigned i = 0; i < p->len; i++)
        tmp[i] = substitute(tmp[i]) ^ 0x5a;
    if (p->flags & 1)
        return -2;
    return handle_kind(p->kind) + tmp[0] + checksum(tmp, p->len);
}

int net_dispatch(int fd) {
    pkt_t pkt;
    ssize_t got = recv(fd, &pkt, sizeof(pkt), 0);
    if (got <= 0)
        return -1;
    return parse_packet(&pkt, (size_t)got);
}

int check_update(const char *arg) {
    if (strcmp(arg, "--no-update") == 0)
        return 0;
    return system(update_url);
}

int checksum(const unsigned char *p, unsigned n) {
    unsigned s = 0;
    for (unsigned i = 0; i < n; i++)
        s = (s << 1) ^ p[i];
    return (int)s;
}

int main(int argc, char **argv) {
    if (argc > 1)
        check_update(argv[1]);
    return net_dispatch(0);
}
